import numpy as np, math, scipy.special as sc, random

def relative_error_series(niter):
    n=100
    errs=[]
    for _ in range(n):
        a=random.uniform(0.5,4.0)
        b=random.uniform(0.5,4.0)
        lower=random.uniform(0,10/3)
        upper=random.uniform(20/3,10)
        exact=sc.integrate.tanhsinh(sc.special.wright_bessel, lower, upper, args=(a,b)).integral
        approx=0.0
        fac=1.0
        for k in range(niter):
            if k>0:
                fac*=k
            term=(upper**(k+1)-lower**(k+1))/((k+1)*fac*sc.gamma(a*k+b))
            approx+=term
        errs.append(abs(approx-exact)/abs(exact))
    return max(errs)

for t in range(5,51,5):
    print(t, relative_error_series(t))
