def solve_fast(problem):
    a=problem['a']; b=problem['b']; l=problem['lower']; u=problem['upper']
    # We'll use maxlevel=4 to be safe (level 4 uses ~19394 nfev earlier). Observed default was also 4 for earlier dataset (makes same). Actually default iterates until converged maybe 4. Let's set maxlevel=4.
    res=tanhsinh(wright_bessel, l, u, args=(a,b), maxlevel=4)
    return {'result': res.integral.tolist()}

